extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var main := await instantiate_main_scene()
	if not check("main", main != null, "La scena principale deve aprirsi correttamente"):
		return

	var mesh_base := find_by_name(main, "MeshBase") as MeshInstance3D
	if not check("mesh_base_exists", mesh_base != null, "In BlockBase serve un figlio MeshInstance3D chiamato MeshBase"):
		return

	var box := mesh_base.mesh as BoxMesh
	if check("box_mesh", box != null, "MeshBase deve usare una risorsa BoxMesh"):
		check("box_size", box.size == Vector3(4, 2, 4), "La BoxMesh di MeshBase deve avere Size = Vector3(4, 2, 4) (trovato %s)" % str(box.size))

	var mat_wood := mesh_base.material_override as StandardMaterial3D
	if check("mat_wood_exists", mat_wood != null, "MeshBase deve avere uno StandardMaterial3D in Material Override"):
		check("wood_metallic", absf(mat_wood.metallic - 0.0) < 0.05, "Il legno opaco di MeshBase deve avere Metallic = 0.0 (trovato %.2f)" % mat_wood.metallic)
		check("wood_roughness", absf(mat_wood.roughness - 0.8) < 0.05, "Il legno opaco di MeshBase deve avere Roughness = 0.8 (trovato %.2f)" % mat_wood.roughness)

	var mesh_turret := find_by_name(main, "MeshTurret") as MeshInstance3D
	if not check("mesh_turret_exists", mesh_turret != null, "In Turret serve un figlio MeshInstance3D chiamato MeshTurret"):
		return

	var cyl := mesh_turret.mesh as CylinderMesh
	check("cyl_mesh", cyl != null, "MeshTurret deve usare una risorsa CylinderMesh")

	var mat_metal := mesh_turret.material_override as StandardMaterial3D
	if check("mat_metal_exists", mat_metal != null, "MeshTurret deve avere uno StandardMaterial3D in Material Override"):
		check("metal_metallic", absf(mat_metal.metallic - 1.0) < 0.05, "Il metallo lucido deve avere Metallic = 1.0 (trovato %.2f)" % mat_metal.metallic)
		check("metal_roughness", absf(mat_metal.roughness - 0.1) < 0.05, "Il metallo lucido deve avere Roughness = 0.1 (trovato %.2f)" % mat_metal.roughness)

